define({"topics":[{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_2.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e33859","topics":[]},{"title":"<span class=\"ph\">Logging on and off<\/span>","shortdesc":"<p class=\"shortdesc\">Use this procedure to log on and off the system.<\/p>","href":"t_LoggingOnandOff_2.html","attributes":{"data-id":"id_2011694"},"menu":{"hasChildren":false},"tocID":"id_2011694-d46e33961","topics":[]},{"title":"<span class=\"ph\">Restarting the host computer<\/span>","shortdesc":"<p class=\"shortdesc\">Restarting the host computer safely shuts down and restarts the system. Restarting the system is often required to finalize changes or updates.<\/p>","href":"t_RestartingTheHostComputer.html","attributes":{"data-id":"id_2002040"},"menu":{"hasChildren":false},"tocID":"id_2002040-d46e34064","topics":[]},{"title":"<span class=\"ph\">Shutting down the host computer<\/span>","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_2.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e34167","topics":[]},{"title":"Image Compute Node (ICN) on\/off procedure for <span class=\"ph\">Dell R640 (Gen 7) and SIP (ICN Gen 8)<\/span>","shortdesc":"<p class=\"shortdesc\">This procedure documents the proper methods of shutdown for the ICNs.<\/p>","href":"t_ICNOnOffProcedure_Sun4100_4170_DellR620_14605825.html","attributes":{"data-id":"id_13106160"},"menu":{"hasChildren":false},"tocID":"id_13106160-d46e34270","topics":[]}]});